definition:
name: showcase-release-notes-to-x
description: When a release ships, draft the X post from its notes and hold it for approval before anything is posted
maxRunCostUsd: 0.5
on:
  webhook: {}
do:
  - id: release
    script.run:
      input: { repo: "tangle-network/agent-runtime" }
      egress: { allowDomains: [api.github.com] }
      timeoutMs: 60000
      source: |
        export default async function run(input: { repo: string }) {
          const res = await fetch("https://api.github.com/repos/" + input.repo + "/releases/latest", { headers: { accept: "application/vnd.github+json", "user-agent": "tangle-workflow" } });
          if (!res.ok) throw new Error("GitHub releases returned " + res.status);
          const r = await res.json();
          const notes = String(r.body || "").replace(/ by @[A-Za-z0-9-]+/g, "");
          console.log(r.tag_name + " published " + r.published_at + "\n" + notes);
          return { repo: input.repo, tag: r.tag_name, publishedAt: r.published_at, url: r.html_url, notes };
        }
  - id: draft
    needs: [release]
    agent.run:
      model: "google/gemini-3.7-flash"
      topology: { inference: {} }
      profile:
        name: release-announcer
        prompt:
          systemPrompt: "You write one X post announcing a software release. At most 260 characters, plain words, no hashtags, no emoji, no people's handles. Name the version and the one change a developer cares about most. Output only the post text."
      prompt: |
        Release ${steps.release.tag} of ${steps.release.repo} (${steps.release.url}).

        Notes:
        ${truncate(steps.release.notes, 4000)}
  - id: approve
    needs: [draft]
    decision:
      title: "Post this release note to X?"
      prompt: "${steps.draft.text}"
      options: [post, discard]
      timeout: 2h
      onTimeout: default
      default: discard
